catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    if (newValue === "internal") {
        switch (g_lang) {
            case "en":
                g_form.setLabelOf('internal_employee', 'Internal employee');
                break;
            case "fq":
                g_form.setLabelOf('internal_employee', 'Employé interne');
                break;
            default:
        }
    } else if (newValue === "mp") {
        switch (g_lang) {
            case "en":
                g_form.setLabelOf('internal_employee', 'Member of the parliament');
                break;
            case "fq":
                g_form.setLabelOf('internal_employee', 'Député');
                break;
            default:
        }
    } else if (newValue === "pps") {
        switch (g_lang) {
            case "en":
                g_form.setLabelOf('internal_employee', 'Parliamentary protective service');
                break;
            case "fq":
                g_form.setLabelOf('internal_employee', 'Service de protection parlementaire');
                break;
            default:
        }
    }
}
